      },
      "bind": "candidates_raw"
    }
  ],
  "rowsets": [
    {
      "from": "candidates_raw",
      "format": "auto_delim",
      "into": "rows",
      "columns": [
        {"into": "product_sku", "candidates": ["product_sku"]},
        {"into": "record_path", "candidates": ["record_path"]},
        {"into": "product_name", "candidates": ["product_name"]}
      ]
    }
  ],
  "compute": [
    {"prim": "column", "args": ["$rows", "product_sku"], "into": "sku_list"},
    {"prim": "first", "args": ["$sku_list"], "into": "product_sku"},
    {"prim": "column", "args": ["$rows", "record_path"], "into": "path_list"},
    {"prim": "first", "args": ["$path_list"], "into": "record_path"},
    {"prim": "column", "args": ["$rows", "product_name"], "into": "name_list"},
    {"prim": "first", "args": ["$name_list"], "into": "product_name"}
  ],
  "decision": {
    "branches": [
      {
        "when": {
          "op": "and",
          "args": [
            {"op": "nonempty", "lhs": "$product_sku", "rhs": null},
            {"op": "nonempty", "lhs": "$record_path", "rhs": null}
          ]
        },
        "label": "found"
      }
    ],
    "default_label": "not_found"
  },
  "ops": [],
  "answer": {
    "found": {
      "message": "We carry {product_name} (SKU: {product_sku}).",
      "outcome": "OUTCOME_OK",
